-- =====================================================================
-- Migration 001 (Phase 2): official media records + media_regions junction.
-- NON-DESTRUCTIVE and IDEMPOTENT: no DROP, no DELETE, no TRUNCATE. Safe to run more than once.
--   * creates media_regions only if it does not exist
--   * inserts or refreshes media_assets rows (fixed ids) with an upsert
--   * adds media links with INSERT IGNORE (existing links are left alone)
-- Apply with:  python -m scripts.migrate_db --plan   then   python -m scripts.migrate_db
-- Needs the migration account (CREATE privilege). Run it only with the owner's approval.
-- =====================================================================

CREATE TABLE IF NOT EXISTS media_regions (
    media_id   INT UNSIGNED      NOT NULL,
    region_id  SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (media_id, region_id),
    KEY ix_media_regions_region (region_id),
    CONSTRAINT fk_medr_media FOREIGN KEY (media_id)
        REFERENCES media_assets (media_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_medr_region FOREIGN KEY (region_id)
        REFERENCES regions (region_id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

AS new ON DUPLICATE KEY UPDATE
    title = new.title, media_type = new.media_type, intended_use = new.intended_use,
    source_url = new.source_url, embed_url = new.embed_url, attribution = new.attribution,
    usage_status = new.usage_status, approval_status = new.approval_status, notes = new.notes;


